window.__saqPaperQuestions("2019-1-northern-sydney",[{"number":1,"title":"","stemText":"(14 marks) You are working in a tertiary emergency department and have an ECG transmitted to you by the ambulance service. The patient is a 45 year old male who has had central chest pain for\nthe last 20 minutes. The estimated time of arrival in your ED is 10 minutes.\nA 12 LEAD ECG IS SHOWN IN THE PROPS BOOKLET, PAGE 1","parts":[{"id":"a","label":"Part A","prompt":"Describe and interpret the critical abnormalities on this ECG? (4 marks)"},{"id":"b","label":"Part B","prompt":"What advice would you offer the paramedics who are transferring the patient? (4 marks) 3 | P a g e"},{"id":"c","label":"Part C","prompt":"The cath lab is unavailable for 2 hours and a decision is made to give a fibrinolytic. List two (2) fibrinolytic agents that could be used and provide a dosing regimen for each (4 marks)"},{"id":"d","label":"Part D","prompt":"Outline a suitable peri-fibrinolysis anti-coagulant regime (2 marks) 4 | P a g e"}],"propPages":["asset:img1230ba854f47293177"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>Hyper acute t wave antero-septal (de Winter)  </em></div><div class=\"answer-line\"><em>Up sloping ST segment V3-V6 </em></div><div class=\"answer-line\"><em>ST elevation I, aVL  </em></div><div class=\"answer-line\"><em>ST depression III, aVF  </em></div><div class=\"answer-line\"> <em>Proximal LAD occlusion  </em></div><div class=\"answer-line\"> <em>Treat as STEMI – lysis or urgent PCI  </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">What advice would you offer the paramedics who are transferring the patient? (4</div><div class=\"answer-line\">marks)</div><div class=\"answer-line\"><em>O2 to maintain sats 92-96%  </em></div><div class=\"answer-line\"><em>Aspirin 300mg oral  </em></div><div class=\"answer-line\"><em>GTN buccal  </em></div><div class=\"answer-line\"><em>Fentanyl/morphine if pain still not controlled  </em></div><div class=\"answer-line\"><em>Transfer directly to cath lab (if available) full monitoring including defib pads </em></div><div class=\"answer-line\"><em>in transit </em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>The cath lab is unavailable for 2 hours and a decision is made to give a fibrinolytic.</td><td></td></tr><tr><td>List two (2) fibrinolytic agents that could be used and provide a dosing regime for</td><td></td></tr><tr><td>each (4 marks)</td><td></td></tr><tr><td>Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</td><td>1 | P a g e</td></tr><tr><td>Alteplase: more than 65 kg: 15 mg intravenous bolus, followed by 50 mg by intravenous</td><td></td></tr><tr><td>infusion over 30 minutes, then 35 mg over the next 60 minutes.</td><td></td></tr><tr><td>65 kg or less: 15 mg intravenous bolus, followed by 0.75 mg/kg by intravenous infusion</td><td></td></tr><tr><td>over 30 minutes, then 0.5 mg/kg over the next 60 minutes</td><td></td></tr><tr><td>OR</td><td></td></tr><tr><td>Retaplase: 10 units intravenous bolus, repeat once after 30 minutes</td><td></td></tr><tr><td>OR</td><td></td></tr><tr><td>Tenectaplase:</td><td></td></tr><tr><td>less than 60 kg: 30 mg (6000 units) intravenous bolus</td><td></td></tr><tr><td>60 to 69 kg: 35 mg (7000 units) intravenous bolus</td><td></td></tr><tr><td>70 to 79 kg: 40 mg (8000 units) intravenous bolus</td><td></td></tr><tr><td>80 to 89 kg: 45 mg (9000 units) intravenous bolus</td><td></td></tr><tr><td>90 kg or more: 50 mg (10 000 units) intravenous bolus.</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Unfractionated heparin 60 units/kg (up to 4000 units) intravenous loading dose, followed by</div><div class=\"answer-line\">12 units/kg/hour (up to 1000 units/hour) by iIV infusion, adjusted according to APTT  OR</div><div class=\"answer-line\">Enoxaparin</div><div class=\"answer-line\">&lt; 75 years: 30mg loading dose then 1mg/kg SCI 12 hly (24 hly if CrCl low)</div><div class=\"answer-line\">&gt; 75 years: no loading dose, variable SCI dose/interval depending on CrCl</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"You have received a prehospital “batcall” about an 86-year-old female nursing home resident with acute respiratory distress who has just had return of spontaneous circulation (ROSC) after arresting in the ambulance en route. She is intubated and has a GCS 3.","parts":[{"id":"a","label":"Part A","prompt":"What is the definition of palliative care? (3 marks)"},{"id":"b","label":"Part B","prompt":"Prescribe one appropriate medication regime or management strategy for each symptom in the palliative semiconscious patient: (4 marks) SYMPTOM DRUG DOSE ROUTE FREQ PAIN AGITATION NAUSEA SECRETIONS 5 | P a g e The patient's daughter appears in the ED distressed. She tells you that her mother would never have wanted this. She has an ACD (Advanced Care Directive) stating not for CPR or ventilation or ICU care. She did not want to be transferred to hospital."},{"id":"c","label":"Part C","prompt":"What information should be in an ACD? (4 marks) After confirming the ACD details and further family discussion, a decision is made to extubate her in ED"},{"id":"d","label":"Part D","prompt":"What preparation is needed? (4 marks) 6 | P a g e"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">-life limiting illness includes cancer and chronic disease</div><div class=\"answer-line\">-focus on quality of life</div><div class=\"answer-line\">-treatment that is not aimed at a cure</div><div class=\"answer-line\">-prevent and treat suffering</div><div class=\"answer-line\">-holistic approach addressing physical, emotional, mental, social and spiritual needs.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Prescribe one appropriate medication regime  or management strategy for each</td><td></td></tr><tr><td>symptom in the palliative semiconscious patient: (4 marks)</td><td></td></tr><tr><td>SYMPTOM</td><td>DRUG DOSE ROUTE FREQ</td></tr><tr><td>PAIN</td><td>Morphine 2.5-5mg SC Q4H</td></tr><tr><td>Fentanyl</td><td>25mcg SC Q4H</td></tr><tr><td>Hydromorphone</td><td>0.5-1mg SC</td></tr><tr><td>AGITATION</td><td>Midazalam 2.5mg SC Q1H</td></tr><tr><td>Haloperidol</td><td>0.5-1mg SC Q4H</td></tr><tr><td>Clonazepam</td><td>0.2-0.5 mg SL/SC Q2H</td></tr><tr><td>NAUSEA</td><td>Metoclopramide 10mg SC Q8H</td></tr><tr><td>Ondansetron</td><td>4-8mg SL/SC Q8H</td></tr><tr><td>Haloperidol</td><td>0.5-1mg SC Q4H</td></tr><tr><td>SECRETIONS</td><td>Hyoscine butylbromide 10-20mg SC Q4H</td></tr><tr><td>Hyoscine hydrobromide</td><td>0.4mg SC Q4H</td></tr><tr><td>Glycopyrrolate</td><td>0.1-0.2mg SC Q4H</td></tr><tr><td>*Or non-pharmo options</td><td></td></tr><tr><td>* Current evidence does not support  use of anti-muscaranic agents  as not superior to</td><td></td></tr><tr><td>placebo.  They may cause adverse effects including delirium and dry mouth. Recommend</td><td></td></tr><tr><td>Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</td><td>3 | P a g e</td></tr><tr><td>non-pharmacological approaches including positioning, and reassurance of family and</td><td></td></tr><tr><td>carers, including staff.</td><td></td></tr><tr><td>The patient&#x27;s daughter appears in the ED distressed. She tells you that her mother would</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">The patient&#x27;s preferences in relation to:</td></tr><tr><td colspan=\"2\">o treatment  goals: active versus comfort care/palliation</td></tr><tr><td colspan=\"2\">o levels of active treatment : ICU care/CPR/ventilation vs ward based care</td></tr><tr><td colspan=\"2\">o transfer to hospital in the event of deterioration</td></tr><tr><td colspan=\"2\">o place of death (eg home, residential aged care facility, hospital)</td></tr><tr><td colspan=\"2\">o after-death care (eg funeral director, preference for cremation or burial,</td></tr><tr><td colspan=\"2\">cultural practices)</td></tr><tr><td></td><td>requests for organ, tissue or body donation</td></tr><tr><td></td><td>names and contact details of substitute decision-maker(s)</td></tr><tr><td></td><td>other issues that are important to the patient (eg religious, care of pet).</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">-document  family discussion and rationale for withdrawing life-saving treatment ie</div><div class=\"answer-line\">extubation</div><div class=\"answer-line\">-explain plan and likely outcome, specifically estimating timing of death, usually hours</div><div class=\"answer-line\">-discontinue unnecessary lines and medications. Turn off monitoring</div><div class=\"answer-line\">-continue palliative medications charted above</div><div class=\"answer-line\">-private room if possible with family present</div><div class=\"answer-line\">-involve social worker and chaplain as appropriate</div><div class=\"answer-line\">-reduce FiO2 and PEEP prior to extubation</div><div class=\"answer-line\">-wait until paralysis wears off, or reverse with Achase inhibitors eg neostigmine  and use</div><div class=\"answer-line\">nerve stimulator Train Of Four to assess adequacy .</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 42 year old female presents with haemoptysis at 19 weeks gestation. She was diagnosed\nwith a pulmonary embolism 1 week after her 3rd delivery. Thrombophilic screen was\nsubsequently negative and the PE was thought to have been pregnancy provoked. In this pregnancy she has been receiving a thromboprohylactic dose of clexane daily. Over the last 7 days she has had rhinorrhoea and sore throat and now has 24 hours of cough with white sputum. Today she has experienced haemoptysis on 3 occasions. No fever recorded during the illness. There are no peripheral signs of DVT. No past history of malignancy. No recent travel or immobilisation. At triage HR 110, BP 100/-, saturations 98% air.","parts":[{"id":"a","label":"Part A","prompt":"Stratify the patient’s risk for pulmonary embolism using a 3 tier model and justify this stratification (4 marks)"},{"id":"b","label":"Part B","prompt":"Outline your approach to d-dimer testing in this patient (3 points) 7 | P a g e"},{"id":"c","label":"Part C","prompt":"List 3 causes of a false negative d dimer? ( 3 points)"},{"id":"d","label":"Part D","prompt":"List 5 ECG findings typically seen in pulmonary embolism (5 marks)\n8 | P a g e"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Stratify the patient’s risk for pulmonary embolism using a 3 tier model and justify</div><div class=\"answer-line\">this stratification (4 marks)</div><div class=\"answer-line\"><em>High risk (on Wells or gestalt) </em></div><div class=\"answer-line\"><em>(state risk factors, alternate diagnosis or elements of Wells or revised Geneva </em></div><div class=\"answer-line\"><em>Wells: signs and symptoms of DVT; PE is likely or equally likely; HR &gt; 100; immobilisation for </em></div><div class=\"answer-line\"><em>&gt;/- 3 days or surgery last month; Prior PE or DVT; Haemoptysis; malignancy within 6 months </em></div><div class=\"answer-line\"><em>or palliative- </em></div><div class=\"answer-line\"><em>Revised Geneva: age &gt; 65; Prior DVT/PE; surgery under GA or LL # past month; active </em></div><div class=\"answer-line\"><em>malignancy; unilateral LL pain; haemoptysis; Hr &gt; 75, &gt; 95; pain on limb palpation) </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Outline your approach to d-dimer testing in this patient (3 points)</div><div class=\"answer-line\">Correct answer could be Y or N so long as justification is sound</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">List 3 causes of a false negative d dimer? ( 3 points)</div><div class=\"answer-line\"><em>(small clot load eg below knee dvt; mature thrombus; defective native fibrinolysis; </em></div><div class=\"answer-line\"><em>immediate post injury; M.F; elderly; recent bleeding; cancer; renal insufficiency; </em></div><div class=\"answer-line\"><em>presence of anticoagulation; collection errors) </em></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">● <em>Sinus tachycardia</em><em><strong> –</strong></em><em> the most common abnormality; seen in 44% of patients.</em><em> </em></div><div class=\"answer-line\">● <em>Complete or incomplete RBBB</em><em><strong> –</strong></em><em> associated with increased mortality; seen in </em></div><div class=\"answer-line\"><em>18% of patients.</em><em> </em></div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</div><div class=\"answer-line\">5 | P a g e</div><div class=\"answer-line\">● <em>Right ventricular strain pattern</em><em><strong> – </strong></em><em> T wave inversions in the right precordial </em></div><div class=\"answer-line\"><em>leads (V1-4) ± the inferior leads (II, III, aVF). This pattern is seen in up to 34% of </em></div><div class=\"answer-line\"><em>patients and is associated with high pulmonary artery pressures.</em><em> </em></div><div class=\"answer-line\">● <em>Right axis deviation – seen in 16% of patients. Extreme right axis deviation may </em></div><div class=\"answer-line\"><em>occur, with axis between zero and -90 degrees, giving the appearance of left </em></div><div class=\"answer-line\"><em>axis deviation (“pseudo left axis”).</em><em> </em></div><div class=\"answer-line\">● <em>Dominant R wave in V1</em><em><strong> </strong></em><em>– a manifestation of acute right ventricular dilatation.</em><em> </em></div><div class=\"answer-line\">● <em>Right atrial enlargement (P pulmonale)</em><em><strong> – </strong></em><em>peaked P wave in lead II &gt; 2.5 mm in </em></div><div class=\"answer-line\"><em>height. Seen in 9% of patients.</em><em> </em></div><div class=\"answer-line\">● <em><strong>S</strong></em><em><strong>I</strong></em><em><strong> Q</strong></em><em><strong>III</strong></em><em><strong> T</strong></em><em><strong>III</strong></em><em><strong>  pattern</strong></em><em> – deep S wave in lead I, Q wave in III, inverted T wave in III. </em></div><div class=\"answer-line\"><em>This “classic” finding is neither sensitive nor specific for pulmonary embolism; </em></div><div class=\"answer-line\"><em>found in only 20% of patients with PE.</em><em> </em></div><div class=\"answer-line\">● <em>Clockwise rotation</em><em><strong> – </strong></em><em>shift of the R/S transition point towards V6 with a </em></div><div class=\"answer-line\"><em>persistent S wave in V6 (“pulmonary disease pattern”), implying rotation of the </em></div><div class=\"answer-line\"><em>heart due to right ventricular dilatation.</em><em> </em></div><div class=\"answer-line\">● <em><strong>Atrial tachyarrhythmias –</strong></em><em> AF, flutter, atrial tachycardia. Seen in 8% of </em></div><div class=\"answer-line\"><em>patients.</em><em> </em></div><div class=\"answer-line\">● <em><strong>Non-specific ST segment and T wave changes</strong></em><em>, including ST elevation and </em></div><div class=\"answer-line\"><em>depression. Reported in up to 50% of patients with PE.</em><em> </em></div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"This question concerns emergency department overcrowding, including its definition, causes, adverse consequences and potential solutions.","parts":[{"id":"a","label":"Part A","prompt":"Define “ED overcrowding” (2 marks)"},{"id":"b","label":"Part B","prompt":"Regarding the causes of ED overcrowding, for each category list two (2) examples (6 marks) Category Examples Input Throughput Output 9 | P a g e"},{"id":"c","label":"Part C","prompt":"Regarding the adverse consequences of ED overcrowding, for each category list two (2) examples (4 marks) Category Examples Patient Effects Staff Effects"},{"id":"d","label":"Part D","prompt":"Regarding potential solutions to ED overcrowding, for each category list two (2) examples (6 marks) Category Examples Input Throughput Output 10 | P a g e"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Define “ED overcrowding”</div><div class=\"answer-line\">ED overcrowding refers to the situation where ED function is impeded primarily</div><div class=\"answer-line\">because the number of patients waiting to be seen, undergoing assessment and</div><div class=\"answer-line\">treatment, or waiting for departure exceeds either the physical bed and/or staffing</div><div class=\"answer-line\">capacity of the ED.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Regarding the causes of ED overcrowding, for each category list two (2) examples (6</td><td>marks)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Regarding the adverse consequences of ED overcrowding, for each category list two</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Regarding potential solutions to ED overcrowding, for each category list two (2)</td><td>examples (6 marks)</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"An obese man is brought to your ED following a rollover MVA. His estimated weight is 210kg. He has head and chest injuries.","parts":[{"id":"a","label":"Part A","prompt":"List four ways in which obesity affects assessment and/or management of the airway and breathing during the primary survey (4 marks)"},{"id":"b","label":"Part B","prompt":"Complete the table identifying two effects of obesity on each component of pharmacokinetics (8 marks)"},{"id":"c","label":"Part C","prompt":"Non-invasive BP measurement is difficult in the obese. Provide a detailed description\n• f the recommended BP cuff bladder width, length and position (3 marks)\n12 | P a g e"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">List four ways in which obesity affects assessment and/or management of the airway</td></tr><tr><td colspan=\"2\">and breathing during the primary survey (4 marks)</td></tr><tr><td></td><td>↑upper airway soft tissues: difficult intubation and airway maintenance</td></tr><tr><td></td><td>↑Pulmonary artery occlusion pressure: increased by high intra-abdominal and</td></tr><tr><td colspan=\"2\">pleural pressures</td></tr><tr><td></td><td>↑Pulmonary artery pressure: mild to moderate elevations may result from OSA</td></tr><tr><td colspan=\"2\">alone</td></tr><tr><td></td><td>↓Total lung capacity</td></tr><tr><td></td><td>↓Vital capacity</td></tr><tr><td></td><td>↓Functional residual capacity: atelectasis and reduced oxygen stores increase</td></tr><tr><td colspan=\"2\">propensity for desaturation</td></tr><tr><td></td><td>↑Pleural pressure: reflects chest wall compression</td></tr><tr><td></td><td>↓Respiratory system compliance: stiffer respiratory system likely from lung and</td></tr><tr><td colspan=\"2\">chest wall contribution</td></tr><tr><td></td><td>↑Airway resistance: risk of asthma and airway closure</td></tr><tr><td></td><td>↓Hypercapnic ventilatory response: contributes to obesity hypoventilation</td></tr><tr><td colspan=\"2\">syndrome</td></tr><tr><td></td><td>↑Upper airway resistance: contributes to difficult airway and sleep apnoea</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Complete the table identifying two effects of obesity on each component of</div><div class=\"answer-line\">pharmacokinetics (8 marks)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Non-invasive BP measurement is difficult in the obese. Provide a detailed description</div><div class=\"answer-line\">of the recommended BP cuff bladder width, length and position (3 marks)</div><div class=\"answer-line\">The most common error in blood pressure measurement is use of inappropriate cuff size.</div><div class=\"answer-line\">Considerable overestimation can occur if the cuff is too small. The bladder length</div><div class=\"answer-line\">recommended by the AHA is 80 percent of the patient’s arm circumference, and the ideal</div><div class=\"answer-line\">width is at least 40 percent. Error is minimized when the cuff width is 46 percent of the arm</div><div class=\"answer-line\">circumference, although for large adult and thigh cuffs this is not practical. In obese</div><div class=\"answer-line\">patients, longer, wider cuffs are needed to compress the brachial artery adequately. In</div><div class=\"answer-line\">children, cuff bladder width should be at least 40 percent of the arm circumference halfway</div><div class=\"answer-line\">between the olecranon and acromion; the cuff should then cover 80 percent or more of the</div><div class=\"answer-line\">arm circumference.</div><div class=\"answer-line\">For correct cuff placement, the midline of the cuff bladder should be positioned over the</div><div class=\"answer-line\">arterial pulsation in the patient’s upper arm following palpation of the brachial artery in the</div><div class=\"answer-line\">antecubital fossa. There should be a 2– to 3–cm space for the stethoscope between the</div><div class=\"answer-line\">lower end of the cuff and the antecubital fossa, unless this would require an undersized</div><div class=\"answer-line\">cuff. In patients with an arm circumference greater than 50 cm, the cuff should be wrapped</div><div class=\"answer-line\">around the forearm, supported at heart level, and the radial pulse felt at the wrist</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"(14 marks)\nAn 85 year old woman is brought to your ED by her daughter who visited her mother at\nhome and found her to be confused. She has early dementia but lives independently. She has mild hypertension and hypercholesterolaemia but is on no regular medications. In the ED she appears to be confused and disoriented. HR 80 regular. BP 155/85. Afebrile.","parts":[{"id":"a","label":"Part A","prompt":"To assess this patient’s cognition, one could use a Mini Mental State Examination or a Six Item Screener. Detail the components of one of these cognitive screening tests (4 marks)"},{"id":"b","label":"Part B","prompt":"Define delirium and identify the key characteristics that differentiate delirium from dementia (4 marks) 13 | P a g e"},{"id":"c","label":"Part C","prompt":"During her stay in the ED she becomes increasingly agitated and aggressive towards the nursing staff. Complete the table detailing one oral and one parenteral medication suitable for use in a behavioural emergency in a delirious elderly patient. Provide an explanatory note identifying cautions, particular indications/contraindications and adverse effects where appropriate (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">To assess this patient’s cognition, one could use a <em>Mini Mental State Examination</em> or</div><div class=\"answer-line\">a <em>Six Item Screener. </em>Detail the components of one of these cognitive screening tests</div><div class=\"answer-line\">(4 marks)</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</div><div class=\"answer-line\">12 | P a g e</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Define delirium and identify the key characteristics that differentiate delirium from</div><div class=\"answer-line\">dementia (4 marks)</div><div class=\"answer-line\">Delirium is defined as “a transient mental disorder, characterised by impaired cognitive</div><div class=\"answer-line\">function and reduced ability to focus, sustain or shift attention”. The symptoms include</div><div class=\"answer-line\">confusion; disorientation; disturbance of the sleep/wake cycle; agitation and aggression or</div><div class=\"answer-line\">quiet withdrawal or sleepiness; emotional disturbances including seeing, hearing or feeling</div><div class=\"answer-line\">things that are not there.</div><div class=\"answer-line\">Dementia develops over time, with a slow progression of cognitive decline. Delirium occurs</div><div class=\"answer-line\">abruptly/acutely, and symptoms can fluctuate during the day. The hallmark separating</div><div class=\"answer-line\">delirium from underlying dementia is inattention.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">During her stay in the ED she becomes increasingly agitated and aggressive towards</div><div class=\"answer-line\">the nursing staff.</div><div class=\"answer-line\">Complete the table detailing one oral and one parenteral medication suitable for use</div><div class=\"answer-line\">in a behavioural emergency in a delirious elderly patient. Provide an explanatory</div><div class=\"answer-line\">note identifying cautions, particular indications/contraindications and adverse</div><div class=\"answer-line\">effects where appropriate (6 marks)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"(16 marks) You are the senior doctor in charge of a tertiary ED at 3pm when Ambulance Control state that there has been an explosion nearby.","parts":[{"id":"a","label":"Part A","prompt":"What 5 pieces of information are important to obtain from Ambulance Control (5 marks)"},{"id":"b","label":"Part B","prompt":"List 7 steps that you should perform after receiving this phone call (7 marks)\n15 | P a g e"},{"id":"c","label":"Part C","prompt":"Patients start arriving rapidly on foot and by ambulance. Using a triage sieve, classify (red, yellow, green) the following patients (4 marks) 1. Female 40s, lying on ambulance stretcher, GCS 14, RR 33, BP 105/80, P 110 2. Male 30s, limping up to triage unassisted, GCS 15, RR 26, BP 95/50, P 105 3. Female 20s, sitting in a wheelchair, obvious compound tibial fracture, GCS 15, RR 28, P 120 4. Male 50s, lying on stretcher, GCS 13, RR 25, BP 105/60, P 110 16 | P a g e"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">(METHANE acronym)</div><div class=\"answer-line\"></div><div class=\"answer-line\">Confirm that a Major Incident has been declared</div><div class=\"answer-line\"></div><div class=\"answer-line\">Exact location</div><div class=\"answer-line\"></div><div class=\"answer-line\">Type of incident</div><div class=\"answer-line\"></div><div class=\"answer-line\">Hazards</div><div class=\"answer-line\"></div><div class=\"answer-line\">(Access/egress)</div><div class=\"answer-line\"></div><div class=\"answer-line\">Number of casualties (total and likely coming to your facility)</div><div class=\"answer-line\"></div><div class=\"answer-line\">(Emergency services present/required)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Declare a Major Incident as per Major Incident Protocol in your hospital  should cascade to</div><div class=\"answer-line\">executive/senior management to co-ordinate roles outside ED</div><div class=\"answer-line\"></div><div class=\"answer-line\">Find/follow major incident role-description cards</div><div class=\"answer-line\"></div><div class=\"answer-line\">Take role of Medical Co-ordinator or Senior Emergency Physician until/unless another more</div><div class=\"answer-line\">appropriate person can</div><div class=\"answer-line\"></div><div class=\"answer-line\">Consider need for decontamination of all patients prior to entering ED</div><div class=\"answer-line\"></div><div class=\"answer-line\">Close all other entry points to ED except one triage route</div><div class=\"answer-line\"></div><div class=\"answer-line\">Liaise with senior nursing and senior management to form key roles: triage officer, resuscitation</div><div class=\"answer-line\">teams, acute patients treating staff, green walking patients treating staff</div><div class=\"answer-line\"></div><div class=\"answer-line\">Assess current ED staffing and potential staffing (who can be called in)</div><div class=\"answer-line\"></div><div class=\"answer-line\">Identify areas to see Resus (red), Acute (yellow) and Walking (green) patients.</div><div class=\"answer-line\"></div><div class=\"answer-line\">Clear the emergency department of as many patients as possible</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Patients start arriving rapidly on foot and by ambulance. Using a triage sieve, classify (red,</div><div class=\"answer-line\">yellow, green) the following patients (4 marks)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A woman unexpectedly gives birth in your emergency department at 38 weeks gestation. You are tasked with resuscitating the newborn. Immediately after cutting the cord a female infant is placed on the resuscitaire in front of you. She is floppy with no spontaneous movement and no respiratory effort She is cyanosed\nHeart rate 50 bpm\nThere is copious meconium stained liquor on the baby","parts":[{"id":"a","label":"Part A","prompt":"Before addressing the airway, what steps will you undertake? (3 marks)"},{"id":"b","label":"Part B","prompt":"Explain why oxygen saturations are measured on the right hand (rather than left hand) of a newborn baby (3 marks)"},{"id":"c","label":"Part C","prompt":"After ensuring adequate head positioning, airway opening & suctioning of secretions the baby still has inadequate respiratory effort. Outline the advantages and disadvantages of a T-piece ventilation device compared to a self- inflating bag in neonatal resuscitation (3 marks) 17 | P a g e"},{"id":"d","label":"Part D","prompt":"List the initial T-piece system settings you would use in this setting (4 marks)\n\nFiO2\nRate PEEP Positive Inspiratory Pressure"},{"id":"e","label":"Part E","prompt":"Describe how you would identify the umbilical vein (for catheter insertion) in an umbilical cord that has just been cut under the clamp (2 marks) 18 | P a g e"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Maintain normal temperature (dry &amp; wrap)</div><div class=\"answer-line\">Stimulate</div><div class=\"answer-line\">Call for additional help</div><div class=\"answer-line\">SpO2 monitoring</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Explain why oxygen saturations are measured on the right hand (rather than left</div><div class=\"answer-line\">hand) of a newborn baby (3 marks)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Option</th><th>Advantage</th><th>Disadvantage</th></tr></thead><tbody><tr><td>After ensuring adequate head positioning, airway opening &amp; suctioning of</td><td></td><td></td></tr><tr><td>secretions the baby still has inadequate respiratory effort. Outline the</td><td></td><td></td></tr><tr><td>Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</td><td>16 | P a g e</td><td></td></tr><tr><td>advantages and disadvantages of a T-piece ventilation device compared to a self-</td><td></td><td></td></tr><tr><td>inflating bag in neonatal resuscitation (3 marks)</td><td></td><td></td></tr><tr><td> T-piece system reliably delivers PEEP. Has manometer to measure/display</td><td></td><td></td></tr><tr><td>actual PEEP. (self-inflating bag with PEEP valve poor in this regard) Important in</td><td></td><td></td></tr><tr><td>recruiting lung volume.</td><td></td><td></td></tr><tr><td> T-piece systems allow blending of room air &amp; O2 – generally use FiO2 21-30%</td><td></td><td></td></tr><tr><td> Self-inflating bag will still work if gas supply fails – T-piece will not</td><td></td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>FiO2</td><td>Start with air – increase &gt; 21% if not reaching target</td></tr><tr><td colspan=\"2\">saturations in time</td></tr><tr><td>Rate</td><td>40-60 breaths/min</td></tr><tr><td>PEEP</td><td>5-8 cm H2O</td></tr><tr><td>Positive Inspiratory</td><td>30 cm H2O (20-12 prem &lt; 32 weeks)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Describe how you would identify the umbilical vein (for catheter insertion) in an</div><div class=\"answer-line\">umbilical cord that has just been cut under the clamp (2 marks)</div><div class=\"answer-line\">Examine the cut end of the cord and identify the two arteries (small, thicker</div><div class=\"answer-line\"></div><div class=\"answer-line\">walled and constricted) and the single vein (more gaping and thin walled).</div><div class=\"answer-line\">Grasp the edge of the cord with a suture forceps and use a probe or the fine</div><div class=\"answer-line\"></div><div class=\"answer-line\">toothed forceps to tease open the vein. It will usually open up easily.</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"One of the ED JMOs approaches you for advice about a 45-year-old female who presented with tinnitus and vertigo. You ask if she has any cerebellar signs but the JMO replies ‘I forgot to check. What should I look for?’","parts":[{"id":"a","label":"Part A","prompt":"What are the components of the cerebellar examination? (4 marks)"},{"id":"b","label":"Part B","prompt":"The patient examines normally except for some decreased hearing in her left ear. What are the ‘tuning fork hearing tests’ and how do you interpret them? (8 marks) Name of How do you perform it? How do you interpret it? test Rinne’s Weber’s 19 | P a g e Your tests confirm that she has sensorineural deafness in the left ear. This patient denies any head injury or other trauma and she is otherwise well."},{"id":"c","label":"Part C","prompt":"Please list the atraumatic causes of this presentation (3 marks) 20 | P a g e"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">● <em>Speech </em></div><div class=\"answer-line\">● <em>Past pointing </em></div><div class=\"answer-line\">● <em>Intention tremor </em></div><div class=\"answer-line\">● <em>Nystagmus  </em></div><div class=\"answer-line\">● <em>Dysdiadochokinesis </em></div><div class=\"answer-line\">● <em>Ataxia  </em></div><div class=\"answer-line\">● <em>Romberg’s negative </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"3\">The patient examines normally except for some decreased hearing in her left ear.</td></tr><tr><td colspan=\"3\">What are the ‘tuning fork hearing tests’ and how do you interpret them? (8</td></tr><tr><td colspan=\"3\">marks)</td></tr><tr><td>Name of test   How do you perform it?</td><td>How do you interpret it?</td><td></td></tr><tr><td>Rinne’s</td><td>Place a (512 Hz) vibrating</td><td>People with normal hearing, and those with</td></tr><tr><td>tuning fork against the</td><td>sensorineural hearing loss,  will hear the</td><td></td></tr><tr><td>patient&#x27;s mastoid bone on</td><td>tuning fork by air conduction after they can</td><td></td></tr><tr><td>that side and ask the</td><td>no longer hear it through bone conduction.</td><td></td></tr><tr><td colspan=\"3\">patient to tell you when</td></tr><tr><td colspan=\"3\">the sound is no longer</td></tr><tr><td colspan=\"3\">heard. Once the patient</td></tr><tr><td colspan=\"3\">People with conductive hearing loss will not</td></tr><tr><td colspan=\"3\">signals they can&#x27;t hear it,</td></tr><tr><td colspan=\"3\">able to hear the tuning fork after it is moved</td></tr><tr><td colspan=\"3\">place the still-vibrating</td></tr><tr><td colspan=\"3\">from the mastoid to the pinna! That’s because</td></tr><tr><td colspan=\"3\">tuning fork 1–2 cm from</td></tr><tr><td colspan=\"3\">their bone conduction is greater than their</td></tr><tr><td colspan=\"3\">the auditory canal. Then</td></tr><tr><td colspan=\"3\">air conduction. Something is inhibiting the</td></tr><tr><td colspan=\"3\">ask the patient again to</td></tr><tr><td colspan=\"3\">passage of sound waves from the ear canal,</td></tr><tr><td colspan=\"3\">indicate when they are no</td></tr><tr><td colspan=\"3\">through the middle ear apparatus and into</td></tr><tr><td colspan=\"3\">longer able to hear the</td></tr><tr><td colspan=\"3\">the cochlea (i.e., there is a conductive hearing</td></tr><tr><td colspan=\"3\">tuning fork.</td></tr><tr><td colspan=\"3\">loss)... but the nerves are fine,</td></tr><tr><td colspan=\"3\">(NB it’s a good idea to</td></tr><tr><td colspan=\"3\">then place the fork close</td></tr><tr><td colspan=\"3\">to your own ear after the</td></tr><tr><td colspan=\"3\">patient indicates that the</td></tr><tr><td colspan=\"3\">sound has subsided, to</td></tr><tr><td colspan=\"3\">compare to your own</td></tr><tr><td>Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</td><td>18 | P a g e</td><td></td></tr><tr><td colspan=\"3\">hearing (this will</td></tr><tr><td colspan=\"3\">differentiate normal</td></tr><tr><td colspan=\"3\">hearing from</td></tr><tr><td colspan=\"3\">sensorineural hearing</td></tr><tr><td colspan=\"3\">loss)</td></tr><tr><td>Weber’s</td><td>Place a vibrating tuning</td><td>● Normal hearing: sound is heard</td></tr><tr><td>fork (256 or 512 Hz) in</td><td>equally in both sides.</td><td></td></tr><tr><td>the middle of the</td><td>● Conductive hearing loss: the defective</td><td></td></tr><tr><td>forehead, or on top of the</td><td>ear hears the sound better</td><td></td></tr><tr><td>head equi-distant from the</td><td>● Sensorineural hearing loss: the</td><td></td></tr><tr><td>patient&#x27;s ears. Ask the</td><td>normal ear hears the sound better</td><td></td></tr><tr><td colspan=\"3\">patient in which ear the</td></tr><tr><td colspan=\"3\">sound is heard louder.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">● <em>Idiopathic- this is the majority of cases </em></div><div class=\"answer-line\">● <em>Medications: aspirin, aminoglycosides </em></div><div class=\"answer-line\">● <em>Vascular e.g. vasculitis, small vessel disease affecting 8th cranial nerve e.g. in </em></div><div class=\"answer-line\"><em>diabetics </em></div><div class=\"answer-line\">● <em>Inflammatory eg sarcoidosis  </em></div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 30-year-old 90kg lady presents to your emergency department having taken a poly-\npharmacy overdose including Panadeine Forte, carbamazepine and temazepam. You are considering treating her with activated charcoal (AC).","parts":[{"id":"a","label":"Part A","prompt":"List 4 general contraindications for this therapy (4 marks)\nAfter a short period, she becomes drowsy, tachycardic (120 bpm) and hypotensive (85/43 mmHg). Further history reveals that she has taken up to 9g of carbamazepine."},{"id":"b","label":"Part B","prompt":"List 4 investigations that should be performed in this patient (4 marks)\n21 | P a g e"},{"id":"c","label":"Part C","prompt":"List 5 clinical features you would expect from a significant carbamazepine overdose\n(5 marks)"},{"id":"d","label":"Part D","prompt":"During your management, the patient has a generalized tonic-clonic seizure. List 4 conditions that should be excluded (4 marks) 22 | P a g e"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">• Patient requiring active resuscitation</div><div class=\"answer-line\">• OD &gt; 1hr ago (controversial)</div><div class=\"answer-line\">• OD of non binding agent – (Metals/Hydrocarbon/Alcohols/Acids/Alkalis)</div><div class=\"answer-line\">• Aspiration risk - potential for seizures or decreasing LOC</div><div class=\"answer-line\">• Benign agent</div><div class=\"answer-line\">• Sub-toxic dose</div><div class=\"answer-line\">• Corrosive agent</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• ECG</div><div class=\"answer-line\">• BSL</div><div class=\"answer-line\">• Paracetamol level</div><div class=\"answer-line\">• HCG</div><div class=\"answer-line\">• Carbamazepine level</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">List 5 clinical features you would expect from a significant carbamazepine overdose</div><div class=\"answer-line\">(5 marks)</div><div class=\"answer-line\">• CNS - decreased LOC/seizures/ataxia/nystagmus</div><div class=\"answer-line\">• CVS - hypotension/tachy-or-brady-arrhythmias, prolonged PR/QRS/QT, pulmonary oedema</div><div class=\"answer-line\">• Anti-cholinergic effects - retention/tachycardia/delirium etc</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">During your management, the patient has a generalized tonic-clonic seizure. List 4</div><div class=\"answer-line\">conditions that should be excluded (4 marks)</div><div class=\"answer-line\">• Hypoglycaemia</div><div class=\"answer-line\">• Hyponatraemia</div><div class=\"answer-line\">• Intracranial pathology</div><div class=\"answer-line\">• Pregnancy with eclampsia</div><div class=\"answer-line\">• Co-ingestant</div><div class=\"answer-line\">• Acute withdrawal</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 23 year old lady presents to your ED following an episode of ‘feeling faint’ with\nsubsequent collapse and brief loss of conscious with spontaneous recovery. Her\n• bservations at triage are normal, she is afebrile and alert. An ECG is performed\nA 12 LEAD ECG IS SHOWN IN THE PROPS BOOKLET, PAGE 3","parts":[{"id":"a","label":"Part A","prompt":"What is your ECG diagnosis? (2 marks)"},{"id":"b","label":"Part B","prompt":"Outline 5 questions on history that you would like to ask (5 marks)"},{"id":"c","label":"Part C","prompt":"List and justify initial bedside ED investigations (5marks)"},{"id":"d","label":"Part D","prompt":"What is your disposition plan for this lady? (1 mark)"}],"propPages":["asset:img8599ec5c1b32d4b08c"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Long QT (concerning for an arrhythmia syncope cause)</div><div class=\"answer-line\">ii.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">-   History of prior syncope or pre-syncope</td></tr><tr><td>-</td><td>Syncope in the setting of inciting event such as exercise. Swimming, emotional event etc</td></tr><tr><td>-</td><td>Hx of palpitations/chest pain</td></tr><tr><td>-</td><td>Family hx of sudden death esp. age under 30</td></tr><tr><td>-</td><td>Confirmed relative with congenital Long QT.</td></tr><tr><td>-</td><td>Personal or family hx of deafness (Jervell, Lang-Nielson)</td></tr><tr><td>-</td><td>Medication use/substance ingestion (e.g. <strong>T</strong>hiazides, <strong>O</strong>piates, (Quinidine,</td></tr><tr><td colspan=\"2\">Quinolone) <strong>R</strong>isperidone, <strong>S</strong>otalol, <strong>A</strong>ntihistamine, ant-<strong>D</strong>epressants TCA,</td></tr><tr><td colspan=\"2\"><strong>E</strong>rythromycin (macrolides) <strong>S</strong>SRI)</td></tr><tr><td>-</td><td>Anything sensible affecting electrolytes (eating disorder, vomiting illness etc.)</td></tr><tr><td colspan=\"2\">iii.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Bloods – including EUC, CMP, May do VBG  (hypoK/Ca/Mg as cause) LFT renal/hepatic</td></tr><tr><td colspan=\"2\">impairment as risks for long QT</td></tr><tr><td>-</td><td>(TSH,  BSL, BHCG) -  alternative cause</td></tr><tr><td>-</td><td>Serial ECG (?dynamic changes) and continuous monitoring (monitor for arrhythmia)</td></tr><tr><td>-</td><td>Postural BP</td></tr><tr><td>-</td><td>Consider bedside Echo ?alternate cause (PE, effusion, etc although clinically unlikely</td></tr><tr><td colspan=\"2\">iv.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Admit to monitored bed under cardiology</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 35 year old woman presents diplopia. She has binocular double vision on both horizontal and vertical gaze. You suspect she has a third cranial nerve palsy.","parts":[{"id":"a","label":"Part A","prompt":"Describe the typical examination findings of a third nerve palsy (3 marks)"},{"id":"b","label":"Part B","prompt":"The location of the site of a third nerve lesion can be predicted by the presence of other symptoms and examination findings (6 marks) Location of lesion Associated symptoms/signs Brainstem/midbrain (e.g. around oculomotor nuclei) Intra-cranial course (e.g. along lateral wall of cavernous sinus Orbital (superior orbital fissure, orbital apex) In the setting of a 3rd nerve palsy, the presence or absence of ipsilateral pupil dilation helps"},{"id":"c","label":"Part C","prompt":"to distinguish between a compressive aetiology (eg. expanding aneurysm) and a microvascular/ischaemic aetiology. Explain. (2 marks)\nList 5 causes of anisocoria (other than 3rd nerve palsy) (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"removedNonQuestionResponseFragments":["Enter your response."],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Binocular horizontal, vertical or oblique diplopia</div><div class=\"answer-line\"></div><div class=\"answer-line\">Paralysis of adduction, elevation &amp; depression  eye looks “down &amp; out”</div><div class=\"answer-line\"></div><div class=\"answer-line\">Ptosis</div><div class=\"answer-line\"></div><div class=\"answer-line\">Pupil dilation (may or may not be present)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">The location of the site of a third nerve lesion can be predicted by the presence of other</td></tr><tr><td colspan=\"2\">symptoms and examination findings (6 marks)</td></tr><tr><td>Location of lesion</td><td>Associated symptoms/signs</td></tr><tr><td>Brainstem/midbrain (e.g.</td><td>Dizziness, vertigo, ataxia, aphasia</td></tr><tr><td>around oculomotor nuclei)</td><td>“Crossed signs” - contralateral cerebellar deficits or contralateral hemi-</td></tr><tr><td colspan=\"2\">paresis</td></tr><tr><td>Intra-cranial course (e.g.</td><td>Involvement of other CN  - 4th, 5th, 6th</td></tr><tr><td colspan=\"2\">along lateral wall of</td></tr><tr><td colspan=\"2\">cavernous sinus</td></tr><tr><td>Orbital (superior orbital</td><td>Orbital signs – chemosis, conjunctival injection, proptosis, visual loss,</td></tr><tr><td colspan=\"2\">4th, 6th</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">to distinguish between a compressive aetiology (eg. expanding aneurysm) and a</div><div class=\"answer-line\">microvascular/ischaemic aetiology. Explain.  (2 marks)</div><div class=\"answer-line\">Pupil constriction is mediated by parasympathetic fibres that accompany CN III – they travel</div><div class=\"answer-line\">peripherally &amp; are more susceptible to compression resulting in pupil dilation (from unopposed</div><div class=\"answer-line\">sympathetic supply)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 26 year old primigravida presents at 36 weeks gestation with jaundice, blurred vision and hypertension (180/100 mmHg). The antenatal period was otherwise unremarkable. The following are her blood results:\n\nHb 80g/L\n(115 - 160)\n\nPlatelets 52 x 109/L\n(140 - 400)\n\nINR 1.8\n(0.9 - 1.3)\n\nAPTT 55 seconds\n(25 - 38)\nLDH 654 U/L\n(110 - 250)\nFibrinogen 1.0 G/L\n(1.5 - 4.0)\nTotal bilirubin 51 micromol/L (< 20)","parts":[{"id":"a","label":"Part A","prompt":"List the four most likely diagnoses for this clinical presentation (4 marks)"},{"id":"b","label":"Part B","prompt":"Outline 4 priorities in your management (4 marks)"},{"id":"c","label":"Part C","prompt":"She starts to have a generalised seizure. List 2 medications with doses that you might administer (2 marks)"},{"id":"d","label":"Part D","prompt":"List the findings on a cardiotocograph (CTG) trace that would indicate foetal distress (4 marks) CTG feature Non-reassuring or abnormal values Baseline rate Decelerations"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>Pre-eclampsia </strong></div><div class=\"answer-line\"></div><div class=\"answer-line\">HELLP Syndrome</div><div class=\"answer-line\"></div><div class=\"answer-line\">HUS – TTP</div><div class=\"answer-line\"></div><div class=\"answer-line\">Biliary disease</div><div class=\"answer-line\"></div><div class=\"answer-line\">Acute fatty liver of pregnancy</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">• IV access and resus</div><div class=\"answer-line\">• Contact O&amp;G, anaesthetics, paediatrics – may require immediate delivery of baby</div><div class=\"answer-line\">• Treat hypertension – IV hydralazine 5mg every 5 - 10 minutes, aim SBP &lt;150, DBP &lt;105</div><div class=\"answer-line\">• Prevention of seizures – MgSO4 4g IV</div><div class=\"answer-line\">• Consider correction coagulopathy</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">She starts to have a generalised seizure. List 2 medications with doses that you might</div><div class=\"answer-line\">administer (2 marks)</div><div class=\"answer-line\"></div><div class=\"answer-line\">4g Magnesium followed by 1g/hour magnesium infusion, Mg can be repeated every 5</div><div class=\"answer-line\">minutes 2g</div><div class=\"answer-line\"></div><div class=\"answer-line\">BZD – midazolam 5mg IV, not first line</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">List the findings on a cardiotocograph (CTG) trace that would indicate foetal distress (4</div><div class=\"answer-line\">marks)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"The time to transfer of care (TOC) from ambulance stretcher to your ED (“off-stretcher” time) deteriorated recently.","parts":[{"id":"a","label":"Part A","prompt":"What are the adverse effects of prolonged TOC times? (4 marks) To address this problem an increasing number of patients have been sent directly from the ambulance bay to the Emergency Medicine Unit (EMU). Unfortunately, there have been a number of incidents in your EMU where patients have unexpectedly deteriorated during their stay."},{"id":"b","label":"Part B","prompt":"What is the role of an EMU or ED Short Stay Unit? (2 Marks)"},{"id":"c","label":"Part C","prompt":"How would you develop a solution to the increased number of patients deteriorating in EMU? (4 Marks)"},{"id":"d","label":"Part D","prompt":"You have been asked to develop a set of exclusion criteria for your Short Stay Unit. Please list your exclusion criteria ? (4 Marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Delayed access to definitive assessment and care in the acute hospital setting1, with these</div><div class=\"answer-line\">delays likely to be associated with the same poor outcomes already known to be associated</div><div class=\"answer-line\">with delayed emergency department care2.</div><div class=\"answer-line\">cover the same geographic areas1. This is reflected in deteriorating response times for</div><div class=\"answer-line\">critical and emergent patients.</div><div class=\"answer-line\">and flexibility, or increases ambulance service and community costs due to additional</div><div class=\"answer-line\">overtime or the need for additional crews and ambulances1.</div><div class=\"answer-line\">hospitals, as ramping affects key performance measures for ambulance services and EDs.</div><div class=\"answer-line\">leading to poor staff morale and poor public perceptions of key areas of the health system</div><div class=\"answer-line\">and personnel within that system.</div><div class=\"answer-line\">ct between patients, paramedics and ED staff1.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><em>To  manage  Emergency  Medicine  patients  who  would  benefit  from  extended  treatment  </em></div><div class=\"answer-line\"><em>and observation  but  have  an  expected  length  of  stay  of  less  than  24 hours.   </em></div><div class=\"answer-line\"><em>Taken  from  Cameron  Textbook  of  Adult  Emergency  Medicine  3rd  Edition  Section  27.2   </em></div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">How would  you  develop  a  solution  to  the increased number of patients</div><div class=\"answer-line\">deteriorating in EMU?  (4  Marks)</div><div class=\"answer-line\"><em>Gather  information  -  1  Mark   </em></div><div class=\"answer-line\"><em>Develop  solution  plan  -  1  Mark   </em></div><div class=\"answer-line\"><em>Implement  plan  -  1  Mark   </em></div><div class=\"answer-line\"><em>Audit  /  Re-collect  data  -  1  Mark   </em></div><div class=\"answer-line\"><em>Note  exact  wording  not  essential  but  plan  must  include  aspects  of  each  of  these  </em></div><div class=\"answer-line\"><em>domains  to  score  maximum  marks   </em></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">You  have  been  asked  to  develop  a  set  of  exclusion  criteria  for  your  Short  Stay</div><div class=\"answer-line\">Unit.  Please  list  your  exclusion  criteria  ?  (4  Marks)</div><div class=\"answer-line\"><em>Patients  who  should  be  admitted  to  in-patient  wards  -  complex  medical  or  surgical  </em></div><div class=\"answer-line\"><em>problems   </em></div><div class=\"answer-line\"><em>Multiple  problems   </em></div><div class=\"answer-line\"><em>Elderly  patient ?  </em></div><div class=\"answer-line\"><em>Paediatric  patients   </em></div><div class=\"answer-line\"><em>Patients  without  clear  management  plan  /  diagnosis   </em></div><div class=\"answer-line\"><em>Patients  with  intensive  nursing  requirements   </em></div><div class=\"answer-line\"><em>Risk  to  staff  patients  -  psychotic,  violent,  forensic  history   </em></div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 23 year-old female is brought to your ED following a high speed motor vehicle accident.\nShe has normal vital signs but has tenderness in her right upper abdomen with no peritoneal signs. Secondary survey reveals no other injuries.","parts":[{"id":"a","label":"Part A","prompt":"Outline the role of the abdominal FAST scan in haemodynamically stable blunt trauma patients (3 marks) An abdominal FAST scan is performed in this patient AN IMAGE FROM THE FAST SCAN IS SHOWN IN THE PROPS BOOKLET, PAGE 4"},{"id":"b","label":"Part B","prompt":"Describe the findings in the right upper quadrant on this FAST scan image (2 marks)"},{"id":"c","label":"Part C","prompt":"What are the pitfalls and limitations of FAST ultrasound scanning in trauma (4 marks)"},{"id":"d","label":"Part D","prompt":"Discuss the advantages and disadvantages of whole body CT scanning (“pan scan”) versus selective imaging in trauma (4 marks)"},{"id":"e","label":"Part E","prompt":"Complete the following table relating to ionising radiation arising from CT imaging (4 marks) Dose (mSv) Equivalent number of Equivalent period of chest X-rays natural background radiation (years) Head CT CT abdomen/pelvis"}],"propPages":["asset:img9463e55a33d05d5ea6"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Outline the role of the abdominal FAST scan in haemodynamically <em>stable</em> blunt</div><div class=\"answer-line\">trauma patients (3 marks)</div><div class=\"answer-line\"> Clear role for FAST in <em>unstable</em> blunt trauma (guides decisions about going to OT…)</div><div class=\"answer-line\"> In stable patients, sensitivity of FAST in detecting significant injury is poor (&lt; 50% -</div><div class=\"answer-line\">i.e. lots of false negatives – doesn’t “rule out” the disease)</div><div class=\"answer-line\"> In particular misses hollow viscus &amp; retroperitoneal injury and doesn’t assess solid</div><div class=\"answer-line\">organ injury (with view to non-operative Mx)</div><div class=\"answer-line\"> There is no evidence base to recommend FAST in this context.  Decisions about CT</div><div class=\"answer-line\">scan/laparotomy/observation need to be based on other patient findings</div><div class=\"answer-line\"> May be useful for clinician practice and possibly a role for serial FAST in a stable</div><div class=\"answer-line\">patient admitted for observation</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Possible hypoechoic stripe adjacent to kidney – wedge-shaped and bounded by echoic lines</div><div class=\"answer-line\">– likely represents perinephric fat rather than free fluid. (1 mark for adequate description, 1</div><div class=\"answer-line\">mark for correct interpretation)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"> Operator dependent</td></tr><tr><td colspan=\"2\"> Technical difficulties – obesity, subcutaneous air</td></tr><tr><td colspan=\"2\"> Requires &gt; 250 mL blood to collect to become positive</td></tr><tr><td colspan=\"2\"> Doesn’t look at retroperitoneal space, hollow viscera or solid organs</td></tr><tr><td colspan=\"2\"> Role in pelvic trauma unclear</td></tr><tr><td colspan=\"2\"> Doesn’t identify source of bleeding</td></tr><tr><td colspan=\"2\"> Doesn’t distinguish other sources of IP fluid (peritoneal dialysis, ascites, ruptured</td></tr><tr><td colspan=\"2\">ovarian cyst etc</td></tr><tr><td colspan=\"2\"> False positive  unnecessary further imaging/operation</td></tr><tr><td></td><td>Opportunity cost, in terms of staffing resources and time for other procedures ie.</td></tr><tr><td colspan=\"2\">People dicking around with the probe instead of getting on with definitive care</td></tr><tr><td></td><td>Trauma patients non-fasted and limitations with bowel gas</td></tr><tr><td></td><td>Evidence for use in Paediatric population limited and due to primarily</td></tr><tr><td colspan=\"2\">conservative approach in kids for blunt trauma - limited utility in decision</td></tr><tr><td colspan=\"2\">making.</td></tr><tr><td colspan=\"2\">Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Option</th><th>Advantage</th><th>Disadvantage</th></tr></thead><tbody><tr><td>Discuss the advantages and disadvantages of whole body CT scanning (“pan scan”)</td><td>versus selective imaging in trauma (4 marks)</td><td>Controversial area.  Biggest study is REACT-2 which found</td></tr><tr><td> No mortality benefit in WBCT</td><td> Time to identifying injuries shorter (50 minutes versus 58 min)</td><td> No difference in total radiation dose (both groups ~ 20mSv) – though the range of</td></tr><tr><td>dose in the selective group 9-22 mSv</td><td></td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Complete the following table relating to ionising radiation arising from CT imaging (4</div><div class=\"answer-line\">marks)</div><div class=\"answer-line\">Dose (mSv)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 25 year old man presents 6 hours after a SCUBA dive with a possible decompression sickness (DCS)","parts":[{"id":"a","label":"Part A","prompt":"List 6 questions specific to diving that you should ask in your history (6 marks)"},{"id":"b","label":"Part B","prompt":"Complete the table listing 3 symptoms or signs of DCS in each"},{"id":"c","label":"Part C","prompt":"Complete the table contrasting DCS and Arterial Gas Embolism ("}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Dive profile (ideally from log book or computer)  – depth, times, ascent rates, surface</div><div class=\"answer-line\">intervals, safety/decompression stops</div><div class=\"answer-line\"></div><div class=\"answer-line\">Dives in excess of tables?</div><div class=\"answer-line\"></div><div class=\"answer-line\">Multiple dives in one day?</div><div class=\"answer-line\"></div><div class=\"answer-line\">Altitude/flight since dive</div><div class=\"answer-line\"></div><div class=\"answer-line\">Any problems during descent/ascent  – problems equalising? Equipment issues? Incidents?</div><div class=\"answer-line\"></div><div class=\"answer-line\">Delay to symptom onset after leaving water</div><div class=\"answer-line\"></div><div class=\"answer-line\">Previous dive experience</div><div class=\"answer-line\"></div><div class=\"answer-line\">Previous dive-related illness</div><div class=\"answer-line\">ii.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Category</td><td>Symptom/Sign</td></tr><tr><td>Neurological</td><td>Weakness, headache, paralysis, dizziness, visual</td></tr><tr><td colspan=\"2\">disturbance, vertigo, altered LOC, paraesthesia,</td></tr><tr><td colspan=\"2\">urinary retention</td></tr><tr><td>Other</td><td>SOB, rash, itching, joint/muscle aches, chest</td></tr><tr><td colspan=\"2\">pain</td></tr><tr><td colspan=\"2\">iii.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>DCS</td><td>AGE</td><td></td></tr><tr><td>Pathophysiology</td><td>Nitrogen bubbles forming in tissues</td><td>Barotrauma – rapid expansion/tear of</td></tr><tr><td>(pressure effects) and vessels (flow</td><td>pulmonary tissue – direct entry of</td><td></td></tr><tr><td>effects) &amp; activation of inflammatory</td><td>bubbles into arterial circulation</td><td></td></tr><tr><td colspan=\"3\">cascade</td></tr><tr><td>Time of onset</td><td>Gradual onset of neuro, MSK and/or</td><td>Usually occurs on ascent or</td></tr><tr><td>skin symptoms – often within 30-60</td><td>immediately upon surfacing</td><td></td></tr><tr><td colspan=\"3\">minutes of surfacing – nearly all</td></tr><tr><td colspan=\"3\">within 24 hours</td></tr><tr><td colspan=\"3\">Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A five-year old boy has been kicked in the face by a horse and has been brought to your rural base hospital by ambulance. He is unconscious, has extensive facial injuries and partial airway obstruction.\n\nVital signs:\n\nHR 140\nSBP 80\n\nGCS 3\n\nSats 85%\nAt laryngoscopy the view is obscured by anatomical derangement, massive tongue swelling, blood and debris and he cannot be oro-tracheally intubated.","parts":[{"id":"a","label":"Part A","prompt":"Explain why partial/complete upper airway obstruction is a relative contraindication to percutaneous transtracheal ventilation (3 marks)"},{"id":"b","label":"Part B","prompt":"Describe a method for connecting a bag-valve device to a 16-gauge catheter that has been inserted successfully through the cricothyroid membrane (3 marks)"},{"id":"c","label":"Part C","prompt":"Outline the ventilation parameters you would use if a commercially available jet ventilation device with variable-flow oxygen is available (3 marks)"},{"id":"d","label":"Part D","prompt":"List 5 complications of percutaneous transtracheal ventilation (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Explain why partial/complete upper airway obstruction is a relative contraindication</div><div class=\"answer-line\">to percutaneous transtracheal ventilation (3 marks)</div><div class=\"answer-line\">In routine use of percutaneous transtracheal ventilation (PTV) through a catheter, much of</div><div class=\"answer-line\">the expired air comes out of the mouth and nose. Thus, with complete upper airway</div><div class=\"answer-line\">obstruction, egress of expired air is difficult. Initial studies in animals suggested that PTV in</div><div class=\"answer-line\">the setting of complete upper airway obstruction led to development of massive distension</div><div class=\"answer-line\">of lungs, severe barotrauma, and death Subsequent studies have shown successful use of</div><div class=\"answer-line\">PTV in settings of complete upper airway obstruction using modified techniques that consist</div><div class=\"answer-line\">of prolonged expiratory time, larger internal diameter catheters, and lower oxygen flow</div><div class=\"answer-line\">rates.</div><div class=\"answer-line\">PTV may be used successfully in partial laryngeal obstruction as the &quot;ball-valve&quot; effect, while</div><div class=\"answer-line\">constraining natural inspiration, adequately permits exhalation For infants and young</div><div class=\"answer-line\">children with complete upper airway obstruction and where other methods have been</div><div class=\"answer-line\">unsuccessful, it is reasonable to use PTV. Ventilatory methods should use a longer</div><div class=\"answer-line\">expiratory time (eg, I:E ratio of 1:8 to 1:10), lower oxygen delivery pressure and flow rate,</div><div class=\"answer-line\">and as large a catheter as possible. In addition, the clinician should carefully monitor for</div><div class=\"answer-line\">chest rise and fall with inspiration and expiration. Diminished chest fall with expiration</div><div class=\"answer-line\">should lead to further reduction in respiratory rate, longer expiratory time, and emergent</div><div class=\"answer-line\">chest radiography to look for signs of pulmonary barotrauma.</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Describe a method for connecting a bag-valve device to a 16-gauge catheter that has</div><div class=\"answer-line\">been inserted successfully through the cricothyroid membrane (3 marks)</div><div class=\"answer-line\"><strong>Bag-valve-mask connector options</strong> — If a bag-valve-mask will be used for patient</div><div class=\"answer-line\">ventilation, then it should connect to the catheter using one of the following improvised</div><div class=\"answer-line\">adapters:</div><div class=\"answer-line\">10ml syringe with plunger removed – insert small ETT and inflate cuff</div><div class=\"answer-line\">Three mL Luer lock syringe with plunger removed with 7.5 mm ID endotracheal tube</div><div class=\"answer-line\">connector (bag-valve-mask connector)</div><div class=\"answer-line\">3.0 mm ID endotracheal tube connector attached directly to the catheter (bag-valve-</div><div class=\"answer-line\">mask connector)</div><div class=\"answer-line\">2.5 mm ID endotracheal tube connector attached to cut off IV tubing with Luer lock</div><div class=\"answer-line\">end connected directly to the catheter</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Outline the ventilation parameters you would use if a commercially available jet</div><div class=\"answer-line\">ventilation device with variable-flow oxygen is available (3 marks)</div><div class=\"answer-line\">Begin regular ventilation by intermittently opening and closing the in-line valve; by</div><div class=\"answer-line\">intermittently occluding the side port, y-connector, or stopcock; or by ventilations with</div><div class=\"answer-line\">the self-inflating resuscitation bag, depending on the system in use.</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</div><div class=\"answer-line\">●Use I:E ratio of 1:4 to 1:5, with a breath rate of 10 to 12/minute for most children.</div><div class=\"answer-line\">Change the ratio to 1:2 to 1:3 with a breath rate of 15 to 20/minute in the setting of</div><div class=\"answer-line\">increased intracranial pressure to improve CO2 elimination. With partial or complete</div><div class=\"answer-line\">upper airway obstruction, use the ratio of 1:8 to 1:10 with a breath rate of 5 to</div><div class=\"answer-line\">6/minute to reduce the risk of pulmonary barotrauma. Adjust these ratios based on</div><div class=\"answer-line\">clinical monitoring, blood gas measurements, and chest radiography.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Unsuccessful catheter placement <strong>OR</strong> Successful</td><td>Inability to ventilate</td></tr><tr><td colspan=\"2\">catheter placement with subsequent</td></tr><tr><td colspan=\"2\">Subcutaneous emphysema</td></tr><tr><td colspan=\"2\">obstruction, kinking, or dislodgement</td></tr><tr><td>Barotrauma</td><td>Subcutaneous emphysema</td></tr><tr><td colspan=\"2\">Pneumomediastinum</td></tr><tr><td colspan=\"2\">Pneumothorax</td></tr><tr><td colspan=\"2\">Pneumatocele of the larynx</td></tr><tr><td>Damage to adjacent structures</td><td>Posterior tracheal laceration or</td></tr><tr><td colspan=\"2\">perforation</td></tr><tr><td colspan=\"2\">Esophageal perforation</td></tr><tr><td colspan=\"2\">Mediastinitis</td></tr><tr><td colspan=\"2\">Vocal cord injury</td></tr><tr><td colspan=\"2\">Laryngeal injury and/or laryngospasm</td></tr><tr><td>Excessive bleeding</td><td>Hematoma (cutaneous and/or airway)</td></tr><tr><td colspan=\"2\">with extrinsic or intrinsic airway</td></tr><tr><td colspan=\"2\">narrowing</td></tr><tr><td>Infection</td><td>Cellulitis and abscess (cutaneous and/or</td></tr><tr><td colspan=\"2\">prevertebral)</td></tr><tr><td colspan=\"2\">Tracheitis</td></tr><tr><td colspan=\"2\">Osteomyelitis of the cervical spine</td></tr><tr><td colspan=\"2\">Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 52 year old man presents with back pain.","parts":[{"id":"a","label":"Part A","prompt":"List six (6) clinical features associated with serious underlying causes (“Red Flags”) (6 marks)"},{"id":"b","label":"Part B","prompt":"Recovery from non-specific mechanical back pain is influenced by various psychosocial factors (“Yellow Flags”). List 5 of these (5 marks)"},{"id":"c","label":"Part C","prompt":"The infection causing spinal epidural abscess can arise from many sources. List 4. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">List six (6) clinical features associated with serious underlying causes (“Red Flags”) (6</div><div class=\"answer-line\">marks)</div><div class=\"answer-line\"> Age of onset &lt; 20 and &gt; 55 years</div><div class=\"answer-line\"> Constant, progressive pain not relieved with bed rest</div><div class=\"answer-line\"> Past history of malignancy</div><div class=\"answer-line\"> History of osteoporosis or prolonged corticosteroid use</div><div class=\"answer-line\"> Risk factors for infection – immunosuppression, recent spinal sugery</div><div class=\"answer-line\"> Systemically unwell and/or fever</div><div class=\"answer-line\"> Unexplained weight loss</div><div class=\"answer-line\"> Significant neurological symptoms or signs</div><div class=\"answer-line\"> Structural deformity</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Recovery from non-specific mechanical back pain is influenced by various</div><div class=\"answer-line\">psychosocial factors (“Yellow Flags”). List 5 of these (5 marks)</div><div class=\"answer-line\"> Inappropriate attitudes/beliefs about back pain – belief that pain &amp; activity are</div><div class=\"answer-line\">harmful</div><div class=\"answer-line\"> Abnormal pain behaviour with an inappropriate reduction in activity levels</div><div class=\"answer-line\"> Past/recurring history of back pain</div><div class=\"answer-line\"> Work-related problems/worker’s compensation implications</div><div class=\"answer-line\"> Previous psychological or stress problems</div><div class=\"answer-line\"> Poor coping skills</div><div class=\"answer-line\"> Lack of social support</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">The infection causing spinal epidural abscess can arise from many sources. List 4. (4</div><div class=\"answer-line\">marks)</div><div class=\"answer-line\">Source of infection</div><div class=\"answer-line\">often unknown</div><div class=\"answer-line\">haematogenous spread</div><div class=\"answer-line\">skin/ soft tissue infections</div><div class=\"answer-line\">infected prostheses e.g. IV catheters</div><div class=\"answer-line\">bacterial endocarditis</div><div class=\"answer-line\">pneumonia</div><div class=\"answer-line\">UTI</div><div class=\"answer-line\">contiguous spread</div><div class=\"answer-line\">Vertebral osteomyelitis</div><div class=\"answer-line\">Retropharyngeal abscess</div><div class=\"answer-line\">Overlying skin infections or pressure sores</div><div class=\"answer-line\">Psoas abscess</div><div class=\"answer-line\">Penetrating injury</div><div class=\"answer-line\">Epidural injections or catheters</div><div class=\"answer-line\">Spinal stimulators</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 53 year old man injured his posterior lower leg on sharp steel at a worksite and presents\nwith a 5cm laceration 6 hours later.","parts":[{"id":"a","label":"Part A","prompt":"Wound irrigation is an effective way to remove debris and contaminants and to decrease bacterial counts in traumatic wounds. Describe the usual method of conducting wound irrigation (3 marks)"},{"id":"b","label":"Part B","prompt":"Which wounds are typically considered candidates for Delayed Primary Closure? (2 marks)"},{"id":"c","label":"Part C","prompt":"Describe the technique for Delayed Primary Closure (2 marks)"},{"id":"d","label":"Part D","prompt":"In what circumstances is antibiotic prophylaxis appropriate in traumatic wounds? (5 marks)"},{"id":"e","label":"Part E","prompt":"What are the key points in the wound care instructions that you will give this patient? (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Wound irrigation is an effective way to remove debris and contaminants and to</div><div class=\"answer-line\">decrease bacterial counts in traumatic wounds. Describe the usual method of</div><div class=\"answer-line\">conducting wound irrigation (3 marks)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Anaesthesia (local, block etc) normally used as wound cleaning is painful. Classically</div><div class=\"answer-line\">irrigation is with 0.9% saline (though tap water considered OK) with device delivering</div><div class=\"answer-line\">sufficient pressure (7-10 psi in ED context – operating theatre pulsed jet lavage</div><div class=\"answer-line\">delivers 50-70 psi). Typically a 20 mL syringe and 19 g catheter Need sufficient</div><div class=\"answer-line\">volume – typically 100-300 mL (more for larger and/or visibly contaminated wounds)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Which wounds are typically considered candidates for Delayed Primary Closure? (2</div><div class=\"answer-line\">marks)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Bite wounds, heavily contaminated wounds, wounds with extensive tissue damage,</div><div class=\"answer-line\">wounds presenting late (controversial – duration of concern is anything from 4-12</div><div class=\"answer-line\">hours)</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">At initial encounter, wound cleaned, irrigated, debrided as needed. Pack with saline-soaked</div><div class=\"answer-line\">gauze or equivalent, cover with dressing. Return at about 4-5 days. If wound appears clean,</div><div class=\"answer-line\">uninfected   closure</div><div class=\"answer-line\">vi.</div><div class=\"answer-line\">In what circumstances is antibiotic prophylaxis appropriate in traumatic wounds? (5</div><div class=\"answer-line\">marks)</div><div class=\"answer-line\">Bites, clenched fist injuries, heavily contaminated wounds (soil, faeces etc), wounds with</div><div class=\"answer-line\">significant tissue injury (e.g crushed, macerated, devitalised tissues), stab/penetrating</div><div class=\"answer-line\">injuries, wounds involving deeper structures (e.g. tendon, joint), wound in a limb with</div><div class=\"answer-line\">lymphoedema, delayed presentation (&gt; 8-12h), situations where</div><div class=\"answer-line\">cleaning/irrigation/debridment is difficult</div><div class=\"answer-line\">vii.</div><div class=\"answer-line\">What are the key points in the wound care instructions that you will give this</div><div class=\"answer-line\">patient? (4 marks)</div><div class=\"answer-line\"> Advice on expected course – there will be a scar, fades over 6-12 months</div><div class=\"answer-line\"> Advice on return precautions – e.g. signs of infection – expect 2-5% of wounds to</div><div class=\"answer-line\">become infected</div><div class=\"answer-line\"> Advice about pain management</div><div class=\"answer-line\"> Keep dressing in situ, clean &amp; dry for 48 hours – can then remove to look for</div><div class=\"answer-line\">infection</div><div class=\"answer-line\"> Daily gentle washing with mild soap &amp; water</div><div class=\"answer-line\"> Can continue to dress if makes more comfortable</div><div class=\"answer-line\"> Advice about timing of ROS (about 7 days for the wound in stem)</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"A 40 year old developmentally delayed patient is brought to your ED with vomiting. She had\nPEG inserted 4 weeks ago for feeding. On arrival her GCS is 13 (E4 V3 M6) which is normal\nfor her according to the carers. Sats 95%, RR 13, P 90 BP 140/70, she weighs approximately 40kg. She is on no regular medications.\nA 12 LEAD ECG IS SHOWN IN THE PROPS BOOKLET, PAGE 5","parts":[{"id":"a","label":"Part A","prompt":"Please describe the ECG and provide 3 possible diagnoses (5 marks) Her clinical exam is unremarkable other than dry mucus membranes. Bloods including a VBG are taken. The ambulance crew have NOT placed an IVC\n\npH 7.44\n(7.35 - 7.45)\n\npCO2 47 mmHg\n(35 - 45)\n\nHCO3 42 mmol/L\n(22 - 28)\n\nBE xxxx\n(-3 - + 3)\n\nK 2.0 mmol/L\n(3.4 - 5)\n\nNa 155 mmol/L\n(134 - 146)\n\nCl 129 mmol/L\n(98 - 106)\nGlu 7.4 mmol/L\n3.5 - 5.5)"},{"id":"b","label":"Part B","prompt":"Describe and interpret the VBG and provide a likely differential (5 marks)"},{"id":"c","label":"Part C","prompt":"Outline your immediate management of this case (5 marks)"}],"propPages":["asset:img03b543008955eef2d6"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">SR rate approx 80</div><div class=\"answer-line\">Diffuse ST depression (all chest leads, inferior and lateral) with T wave inversion</div><div class=\"answer-line\">Prominent U waves</div><div class=\"answer-line\">(psuedo) Prolonged QT 480 uncorrected, 550 corrected (do not need values)</div><div class=\"answer-line\">Differential:</div><div class=\"answer-line\">Hypokalaemia – pathognomic</div><div class=\"answer-line\">Ischaemia (but unusual as widespread ST depression)</div><div class=\"answer-line\">Any cause of long QT – drugs (antis) for example. Should name a drug</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Her clinical exam is unremarkable other than dry mucus membranes, bloods</td></tr><tr><td colspan=\"2\">including a VBG are taken. The ambulance crew have NOT placed an IVC. Describe</td></tr><tr><td colspan=\"2\">and interpret the VBG and provide a likely differential (5 marks)</td></tr><tr><td>pH 7.44</td><td>(7.35 – 7.45)</td></tr><tr><td>pCO2 47 mmHg</td><td>(35 – 45)</td></tr><tr><td>HCO3 42 mmol/L</td><td>(22 – 28)</td></tr><tr><td>BE xxxx</td><td>(-3 - + 3)</td></tr><tr><td>K 2.0 mmol/L</td><td>(3.4 – 5)</td></tr><tr><td>Na 155 mmol/L</td><td>(134 – 146)</td></tr><tr><td>Cl 129 mmol/L</td><td>(98 – 106)</td></tr><tr><td>Glu 7.4 mmol/L</td><td>3.5 – 5.5)</td></tr><tr><td colspan=\"2\">Severe / moderate respiratory acidosis and severe metabolic alkalosis with normal pH. (alkalosis</td></tr><tr><td colspan=\"2\">likely pathological process as much more severe)</td></tr><tr><td colspan=\"2\">Severe hypernatraemia</td></tr><tr><td colspan=\"2\">Severe hypokalaemia – life threatening</td></tr><tr><td colspan=\"2\">Differential:</td></tr><tr><td colspan=\"2\">Conns / hyperaldosteronism</td></tr><tr><td colspan=\"2\">Cushings</td></tr><tr><td colspan=\"2\">PEG feed error</td></tr><tr><td colspan=\"2\">Dehydration (severe)</td></tr><tr><td colspan=\"2\">(Note: administration of chloride or sampling error unlikely given NO ivc present)</td></tr><tr><td colspan=\"2\">Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Ensure patient monitored – risk of VT / VF</div><div class=\"answer-line\">Potassium replacement – likely need CVC – 10mmol /hr periph, higher if central access</div><div class=\"answer-line\">Check urinary Cl – high in mineralcorcoid excess, low in dehydration (former resistant to saline,</div><div class=\"answer-line\">latter saline is treatment)</div><div class=\"answer-line\">Check Mg –often severely deplete with hypokalaemia</div><div class=\"answer-line\">Check serum Cl – high in mineralocorticoid excess</div><div class=\"answer-line\">Monitor EUC – 4 hrly</div><div class=\"answer-line\">High risk for deterioration – discussion with family / next of kin regards treatment limitations</div><div class=\"answer-line\">Disposition – monitored bed, likely HDU / ICU</div><div class=\"answer-line\">Northern Sydney Hospitals – SAQ Practice Paper 31 January 2019</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}]);
